class C:
    N = ''
    HEADER = '\033[95m'
    OKBLUE = '\033[94m'
    OKGREEN = '\033[92m'
    WARNING = '\033[93m'
    FAIL = '\033[91m'
    ENDC = '\033[0m'

    @classmethod
    def via_colorama(cls):
        cls.HEADER = '\033[35;40;1m'
        cls.OKBLUE = '\033[36;40;1m'
        cls.OKGREEN = '\033[32;40;1m'
        cls.WARNING = '\033[33;40;1m'
        cls.FAIL = '\033[31;40;1m'

    @classmethod
    def disable(cls):
        cls.HEADER = ''
        cls.OKBLUE = ''
        cls.OKGREEN = ''
        cls.WARNING = ''
        cls.FAIL = ''
        cls.ENDC = ''

    @classmethod
    def oskey(cls, cmd, color = True):
        if sys.platform == 'darwin':
            cmd = cmd.replace('{ctrl+', '{cmd+')
        return cmd.replace('{', C.OKGREEN if color else '`').replace('}', C.ENDC if color else "'")


class Storage:
    def __init__(self, path=os.path.expanduser("~/.ctrl-buff")):
        self.path = path
        self.clean()

    def clean(self):
        self.files = []
        self.dirs = []
        return self

    def load(self):
        try:
            with open(self.path, 'r') as fl:
                (self.files, self.dirs) = json.loads(fl.read())
        except IOError:
            pass
        return self

    def save(self):
        with open(self.path, 'w') as fl:
            fl.write(json.dumps((
                list(set(self.files)),
                list(set(self.dirs)),
            )))
        return self


class normal_cmd:
    "Dumb command"
    AUTOLOAD = False
